+        private bool EnsureMessageListReady()
+        {
+            if (_messageWindow.IsDisposed || _messageWindow.lvErrorCollector.IsDisposed)
+            {
+                return false;
+            }
+
+            if (_messageWindow.lvErrorCollector.IsHandleCreated)
